/**
 * Generates supabase/seed.sql from the publications mock — the same
 * BUSINESSES/PROPERTIES/LISTINGS/… arrays the /listings endpoints serve, so
 * the DB is a straight row copy of src/data (docs/informe-mock-listings §6).
 *
 *   cd apps/api && ./node_modules/.bin/tsx scripts/gen-seed.ts > ../../supabase/seed.sql
 *
 * Availability is generated by the same deterministic buildAvailability() the
 * repo uses — the night window rolls from "today", so regenerate to freshen.
 */
import { buildAvailability } from "../src/data/availability.js";
import { AMENITIES } from "../src/data/catalog.js";
import {
  BUSINESSES,
  LISTINGS,
  LISTING_AMENITIES,
  LISTING_PHOTOS,
  LISTING_UNITS,
  PROPERTIES,
  RATE_RULES,
} from "../src/data/inventory.js";
import { REVIEW_BUSINESS, REVIEW_FIXTURES } from "../src/data/review-fixtures.js";

type Val = string | number | boolean | null | undefined;
const q = (v: Val) =>
  v == null
    ? "null"
    : v === true
      ? "true"
      : v === false
        ? "false"
        : typeof v === "number"
          ? String(v)
          : `'${v.replace(/'/g, "''")}'`;

const insert = (
  table: string,
  cols: string[],
  rows: Val[][],
  chunkSize = 100
) => {
  const out: string[] = [];
  for (let i = 0; i < rows.length; i += chunkSize) {
    const chunk = rows
      .slice(i, i + chunkSize)
      .map((r) => `(${r.map(q).join(",")})`)
      .join(",\n");
    out.push(
      `insert into public.${table} (${cols.join(",")}) values\n${chunk}\non conflict do nothing;`
    );
  }
  return out.join("\n\n");
};

const lines: string[] = [
  "-- nomai seed — publications inventory, a straight row copy of",
  "-- apps/api/src/data. Regenerate:",
  "--   tsx apps/api/scripts/gen-seed.ts > supabase/seed.sql",
  "-- Idempotent (on conflict do nothing). Availability covers ~90 days from",
  "-- generation time — rerun to freshen the bookable window.",
  "",
];

